-- Libros y capítulos (5)
insert into public.books (id, type, title, authors, editor, date, year, pages, isbn, status, link, description, citation, cover, visible, position) values ('book-edunpaz-inf', 'Libro', 'Introducción a la Informática para el Profesorado Universitario en Educación Física', 'Leandro Guerschberg, José Luis Colaciuri, Yael Estefanía Gutiérrez y Karina Guerschberg', 'EDUNPAZ — Editorial Universitaria de la Universidad Nacional de José C. Paz · Colección Morral de Apuntes', '2025', 2025, 'Acceso Abierto', null, 'Publicado', 'https://edunpaz.unpaz.edu.ar/OMP/index.php/edunpaz/catalog/book/157', 'La obra constituye un aporte académico orientado a la formación docente en contextos digitales. Su contenido se organiza en cuatro partes: fundamentos teóricos y pedagógicos, herramientas digitales básicas, aplicaciones didácticas e innovación, y transversalidades con perspectiva pedagógica. A lo largo de los capítulos se abordan conceptos esenciales de hardware, software, TIC, TAC y TEP, y temas como Internet, derechos digitales, software libre, soberanía tecnológica e inteligencia artificial generativa. Asimismo, se incluyen módulos prácticos sobre ofimática, hojas de cálculo y presentaciones digitales, vinculados a las necesidades específicas de la educación física basados en software libre.

Los objetivos principales de la obra son promover una alfabetización digital crítica, brindar herramientas prácticas para la planificación y evaluación docente mediadas por TIC, e impulsar una reflexión ética y pedagógica sobre el uso de tecnologías. Entre sus características distintivas se encuentran la mirada situada en la educación pública, el énfasis en la soberanía digital y la integración del modelo TPACK como marco teórico para la enseñanza mediada por tecnologías.', null, 'assets/libro_edunpaz.svg', true, 0);
insert into public.books (id, type, title, authors, editor, date, year, pages, isbn, status, link, description, citation, cover, visible, position) values ('chap-iaec24', 'Capítulo de libro', 'Desarrollo profesional del tutor para un futuro con Inteligencia Artificial Generativa', 'Guerschberg', 'IAEC24: Diálogo Interamericano sobre Inteligencia Artificial en Educación Científica', '15/10/2024', 2025, 'pp. 92–108', '978-950-29-2073-3', 'Publicado', 'https://iies.aduba.org.ar/wp-content/uploads/2025/12/Midec-2025.pdf', 'El trabajo analiza el desarrollo profesional de los docentes tutores universitarios frente a la incorporación de la Inteligencia Artificial Generativa (IAG), con especial atención a las percepciones, oportunidades y resistencias que genera su uso en las tutorías. A partir de una revisión documental cualitativa y descriptiva de estudios publicados entre 2022 y 2024, el artículo identifica beneficios potenciales como la personalización del aprendizaje, el apoyo a tareas académicas, la automatización de ciertas funciones y la posibilidad de mejorar el acompañamiento de las trayectorias estudiantiles. Sin embargo, también destaca limitaciones vinculadas con la calidad y confiabilidad de los contenidos generados, la desinformación, los sesgos, la integridad académica y el riesgo de una dependencia excesiva de sistemas algorítmicos.

Los resultados muestran que las actitudes docentes frente a la IAG son heterogéneas: algunos profesores rechazan su utilización, otros la incorporan de manera limitada y un tercer grupo avanza hacia usos más innovadores. El estudio sostiene que la IAG puede complementar, pero no sustituir, la interacción humana ni el conocimiento experto del docente tutor, por lo que su integración requiere formación específica, políticas institucionales y criterios éticos claros. En consecuencia, se plantea la necesidad de fortalecer el desarrollo profesional docente para promover un uso crítico, responsable y pedagógicamente significativo de estas tecnologías, preservando valores como la honestidad, la responsabilidad académica y la calidad de la educación superior.', 'Guerschberg, L. (2025). Desarrollo profesional del tutor para un futuro con inteligencia artificial generativa. En I. J. Idoyaga & J. E. Maeyoshimoto (Comps.), Diálogo interamericano sobre inteligencia artificial en educación científica (pp. 92–108). Universidad de Buenos Aires, Instituto de Investigación en Educación Superior. ISBN: 978-950-29-2073-3.', null, true, 1);
insert into public.books (id, type, title, authors, editor, date, year, pages, isbn, status, link, description, citation, cover, visible, position) values ('chap-ciencialatina', 'Capítulo de libro', 'Microaprendizajes en educación superior: ¿tendencia educativa o moda?', 'Guerschberg, Gutierrez', 'Ciencia Latina — Compilación de Estudios Ciencias de la Educación', '2025', 2025, 'pp. 227–258', null, 'Capítulo de libro publicado', 'https://doi.org/10.37811/cli_w1233', 'Análisis empírico y sistemático de las estrategias de microaprendizaje en el aula universitaria, examinando su efectividad y diferenciando modas pasajeras de transformaciones estructurales.', 'Guerschberg, L., & Gutierrez, Y. E. (2025). Microaprendizajes en educación superior: ¿tendencia educativa o moda? En Compilación de Estudios Ciencias de la Educación: Perspectivas sobre la Enseñanza y el Aprendizaje (Vol. 1, Núm. 1, Cap. XIII, pp. 227–258). CID – Centro de Investigación y Desarrollo. https://doi.org/10.37811/cli_w1233', null, true, 2);
insert into public.books (id, type, title, authors, editor, date, year, pages, isbn, status, link, description, citation, cover, visible, position) values ('chap-iberociencias', 'Capítulo de libro', 'La Mirada Disputada', 'Guerschberg', 'Iberociencias — Capítulo de Libro', '2026', 2026, null, null, 'Enviado', null, 'El capítulo analiza cómo la inteligencia artificial generativa transforma tanto la mediación docente como la autoridad epistémica en la educación superior, con foco en la formación en Producción de Bioimágenes de la UNPAZ. A partir de aportes de Kuhn, Chevallard, Foucault y la epistemología social contemporánea, sostiene que la IA no posee una autoridad epistémica autónoma, sino una autoridad testimonial delegada y revisable. En este contexto, el rol docente no desaparece, sino que se redefine como mediación crítica entre el conocimiento disciplinar, los contenidos generados por algoritmos y el saber enseñado. El capítulo propone, finalmente, una autoridad epistémica distribuida que integre la asistencia algorítmica sin desplazar el juicio profesional humano como instancia final de validación diagnóstica.', 'Guerschberg, L. (2026). La Mirada Disputada. En Iberociencias (en proceso editorial).', null, true, 3);
insert into public.books (id, type, title, authors, editor, date, year, pages, isbn, status, link, description, citation, cover, visible, position) values ('book-eliva-1918', 'Libro', 'Evolución del Gobierno de las Universidades Argentinas desde el año 1918', 'LEANDRO GUERSCHBERG', 'Eliva Press, 2025', '7 nov 2025', 2025, '92 páginas', '9999326781, 9789999326780', 'Publicado', null, '¿Cómo se ha configurado el gobierno de nuestras universidades a lo largo de más de un siglo? ¿Quiénes toman las decisiones? ¿Quiénes quedan sistemáticamente al margen? En este ensayo riguroso y profundamente documentado, Leandro Guerschberg nos propone un viaje crítico a través de la historia del gobierno universitario argentino, desde los orígenes de la Reforma Universitaria de 1918 hasta las complejidades institucionales del presente. A partir de una mirada histórica, política y pedagógica, el autor reconstruye el impacto del movimiento reformista, sus conquistas, contradicciones y legados, deteniéndose especialmente en un aspecto muchas veces silenciado: el rol de los/as trabajadores/as universitarios/as, y su lucha aún vigente por una ciudadanía universitaria plena. El texto aborda con claridad los ejes centrales del cogobierno, la autonomía, los conflictos entre tradición y modernización, así como las tensiones persistentes entre los distintos claustros. La Universidad de Buenos Aires se presenta como caso paradigmático, revelando las asimetrías en la representación de docentes, estudiantes, graduados y, en especial, la exclusión del claustro Nodocente en los órganos decisorios. Apoyado en fuentes primarias, marcos teóricos contemporáneos y una escritura ágil pero precisa, este libro no sólo analiza la historia institucional del sistema universitario argentino, sino que interpela al lector desde una perspectiva de justicia, participación y democratización real. Una lectura imprescindible para quienes piensan la educación superior como un campo de disputa, construcción colectiva y transformación social.', null, 'data:image/jpeg;base64,', true, 4);
